package main
import ("encoding/json"; "fmt"; "strings")
// json.Decoder is useful for streaming JSON records.
type Record struct { Name string `json:"name"` }
func main(){input:=`{"name":"Ada"}`;dec:=json.NewDecoder(strings.NewReader(input));var r Record;if err:=dec.Decode(&r);err!=nil{fmt.Println("decode:",err);return};fmt.Println(r.Name)}
